fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0';
if ~exist('fit_resEi800','var')
    ld = load(fullfile(fit_data_path,'FitEn_cut800_1DfSym_dirGH_dE20_fix_bg_slope.mat'));
    fit_resEi800 = ld.fit_res;
end
if ~exist('cuts2fit800','var')
    ld = load('multicuts_fit_dataGH_ei800meV.mat');
    cuts2fit800 = ld.cuts2fit800;
end
cuts2fit = cuts2fit800;
fit_res = fit_resEi800;
mi = maps_instrument(787,600,'A');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for i=1:numel(cuts2fit.cutsS_list)
    cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end

%%
acolor b
Sgnl = fit_res.S;  
pd(Sgnl);ly 0 3;liny;keep_figure %[output:53b0dc8a]
J0 = fit_res.J0;
pd(J0);ly 20 60;keep_figure %[output:6a347349]
G = fit_res.gamma;
G.s_axis.units = 'meV';
pd(G);ly 0 400;keep_figure %[output:51e5a965]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:08ff1c6b]
e_min = Sgnl.x(1);

%%
En = 100 %[output:6f861f0f]
dE_step = 4; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_idx =  floor((En-e_min)/dE)+1;
the2Dcuts = cuts2fit.cutsS_list;%(1:2);
init_fg_params = fit_res.all_fit_par(en_idx).p;
init_bg_params = fit_res.all_fit_par(en_idx).bp;
%init_bg_params = cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false);
[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false) %[output:6dfe09d8] %[output:4d45dcdd] %[output:4df6d2c6] %[output:8a171e4a] %[output:97fcf35a] %[output:0318a43d] %[output:0e8907bd]
wsEn100Ei800 = src(figb);
%%
%fit_res.all_fit_par(en_idx) = fit_par;
acolor r
plot(fit_res.S);ly 0 4;liny; %[output:83a4d1d7]
acolor g
Sgnl.signal(en_idx) = fit_par.p(4);
pd(Sgnl);ly 0 4;liny;keep_figure %[output:83a4d1d7]

acolor r
plot(fit_res.J0);ly 0 100;liny; %[output:0aa52e00]
acolor g
J0.signal(en_idx) = fit_par.p(6);
pd(J0);ly 0 100;keep_figure %[output:0aa52e00]

acolor r
plot(fit_res.gamma);ly 0 300;liny; %[output:7da142ad]
acolor g
G.signal(en_idx) = fit_par.p(3);
pd(G);ly 0 300;keep_figure %[output:7da142ad]


